   377                              $$ = $1;
   378                              $$->negated = false;
   379                          }
   380                  |       '!' host {
   480                              if ($3->tags.follow == UNSPEC)
   481                                  $3->tags.follow = prev->tags.follow;
   482                              if (($3->runasuserlist == NULL &&
   483                                   $3->runasgrouplist == NULL) &&
   484                                  (prev->runasuserlist != NULL ||
