   493  cmndspec        :       runasspec options cmndtag digcmnd {
   494                              struct cmndspec *cs = calloc(1, sizeof(*cs));
   495                              if (cs == NULL) {
   496                                  sudoerserror(N_("unable to allocate memory"));
   497                                  YYERROR;
   498                              }
   499                              parser_leak_add(LEAK_CMNDSPEC, cs);
   500                              if ($1 != NULL) {
   501                                  if ($1->runasusers != NULL) {
   502                                      cs->runasuserlist =
   503                                          malloc(sizeof(*cs->runasuserlist));
   504                                      if (cs->runasuserlist == NULL) {
   505                                          free(cs);
   506                                          sudoerserror(N_("unable to allocate memory"));
   507                                          YYERROR;
   508                                      }
   509                                      /* g/c done via runas container */
   510                                      HLTQ_TO_TAILQ(cs->runasuserlist,
   511                                          $1->runasusers, entries);
   512                                  }
   513                                  if ($1->runasgroups != NULL) {
   514                                      cs->runasgrouplist =
   515                                          malloc(sizeof(*cs->runasgrouplist));
   516                                      if (cs->runasgrouplist == NULL) {
   517                                          free(cs);
   518                                          sudoerserror(N_("unable to allocate memory"));
   519                                          YYERROR;
   520                                      }
   521                                      /* g/c done via runas container */
   522                                      HLTQ_TO_TAILQ(cs->runasgrouplist,
   523                                          $1->runasgroups, entries);
   524                                  }
   525                                  parser_leak_remove(LEAK_RUNAS, $1);
   526                                  free($1);
   527                              }
   528  #ifdef HAVE_SELINUX
   529                              cs->role = $2.role;
